  { name: "Trifecta", url: "https://www.trustpilot.com/review/trifectanutrition.com" },
  { name: "Purple Carrot", url: "https://www.trustpilot.com/review/purplecarrot.com" },
  { name: "Daily Harvest", url: "https://www.trustpilot.com/review/daily-harvest.com" },
  { name: "CookUnity", url: "https://www.trustpilot.com/review/cookunity.com" }
];

const results = [];
for (const item of toCheck) {
  try {
    await tool.navigate({ tabId, url: item.url });
    await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 3000 });
    const info = await browserjs(tabId, () => {
      const title = document.title;
      const text = document.body.innerText;
      const ratingMatch = text.match(/([0-9]\.[0-9])\s*\n*\s*(?:out of 5|stars)?/i) || text.match(/Reviews\s*([0-9,]+)\s*•\s*([0-9\.]+)/i);
      const reviewsMatch = text.match(/([0-9,]+)\s+reviews/i) || text.match(/Reviews\s*([0-9,]+)/i);

      const summaryStart = text.indexOf("Created with AI");
      let summary = "";
      if (summaryStart !== -1) {
        summary = text.slice(summaryStart, summaryStart + 350).replace(/\n/g, ' ');
      } else {
        summary = text.split('\n').filter(l => l.length > 50).slice(0, 3).join(' | ');
      }

      return { title, ratingMatch: ratingMatch ? ratingMatch[0] : null, reviewsMatch: reviewsMatch ? reviewsMatch[0] : null, summary };
    });
    results.push({ name: item.name, url: item.url, ...info });
  } catch (e) {
    results.push({ name: item.name, url: item.url, error: e.message });
  }
}

