    const nextBtn = Array.from(document.querySelectorAll('button')).find(b => b.innerText.trim() === 'Next' || b.innerText.trim() === 'Select Plan' || b.innerText.includes('Continue'));
    if (nextBtn) {
      nextBtn.click();
      return false;
    }
    return true;
  });
  if (isPlans) break;
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 2000 });
}

