// Find the ZIP code input and fill it
const res = await browserjs(tabId, () => {
  const zipInput = document.querySelector('input[placeholder*="ZIP"], input[name*="zip"], input[type="text"]');
  if (zipInput) {
    zipInput.value = "10001";
    zipInput.dispatchEvent(new Event('input', { bubbles: true }));
    zipInput.dispatchEvent(new Event('change', { bubbles: true }));
    const submitBtn = document.querySelector('button[type="submit"]') || Array.from(document.querySelectorAll('button')).find(b => b.innerText.includes("Unlock") || b.innerText.includes("Order"));
    if (submitBtn) submitBtn.click();
    return { success: true, btnText: submitBtn ? submitBtn.innerText : null };
  }
  return { success: false };
});
console.log(res);
