  { name: "CookUnity", url: "https://www.trustpilot.com/review/cookunity.com" }
];

const results = [];
for (const item of toCheck) {
  try {
    await tool.navigate({ tabId, url: item.url });
    await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 3000 });
