      const reviewsMatch = text.match(/([0-9,]+)\s+reviews/i) || text.match(/Reviews\s*([0-9,]+)/i);

      const summaryStart = text.indexOf("Created with AI");
      let summary = "";
      if (summaryStart !== -1) {
        summary = text.slice(summaryStart, summaryStart + 350).replace(/\n/g, ' ');
      } else {
        summary = text.split('\n').filter(l => l.length > 50).slice(0, 3).join(' | ');
      }

      return { title, ratingMatch: ratingMatch ? ratingMatch[0] : null, reviewsMatch: reviewsMatch ? reviewsMatch[0] : null, summary };
    });
    results.push({ name: item.name, url: item.url, ...info });
  } catch (e) {
    results.push({ name: item.name, url: item.url, error: e.message });
  }
}

console.log(JSON.stringify(results, null, 2));

